FurtherInfo = {
	init: async function(app, container) {
    	app = app || session.app;
        container = container || $(".component[name=FurtherInfo]");
        $("[name=downloadPresentation]", container).on("click", async (e) => await FurtherInfo.downloadPresentation(e, app));
        var furtherInfoFiles = (await api.get("DocumentManagement/Folder?$filter=AppId eq " + app.Id + " and Path eq 'furtherinformation'&$expand=Files")).value[0];
        FolderManagement.init(app, $(".component[name=FolderManagement]", $("[name=furtherInfoFolder]", container)), furtherInfoFiles, true, true);
        var legalFiles = (await api.get("DocumentManagement/Folder?$filter=AppId eq " + app.Id + " and Path eq 'furtherinformation/legal'&$expand=Files")).value[0];
        FolderManagement.init(app, $(".component[name=FolderManagement]", $("[name=legalFolder]", container)), legalFiles, true, true);
    },

};
